if [ "$LIST" = 1 ]; then
  payload | tar -tzf - | grep -v '/$'
  exit 0
fi

mkdir -p "$TARGET"
cd "$TARGET"

echo "Writing 1051 files into $(pwd) ..."
payload | tar -xzf -
echo "Done."

if [ "$VERIFY" = 1 ]; then
  if command -v sha256sum >/dev/null 2>&1; then SHA="sha256sum -c --quiet"; else SHA="shasum -a 256 -c --quiet"; fi
  if checksums | $SHA; then echo "Verify: all 1051 files match."; else echo "Verify: MISMATCH (see above)." >&2; exit 1; fi
fi

if [ "$PRUNE" = 1 ]; then
  MANIFEST=$(mktemp); trap 'rm -f "$MANIFEST"' EXIT
  checksums | sed 's/^[0-9a-f]*  //' > "$MANIFEST"
  del() {
    if [ "$DRYRUN" = 1 ]; then echo "would delete: $1"; else rm -f -- "$1"; echo "deleted: $1"; fi
  }
  # 1. old locations of moved modules
  oldpaths | while IFS= read -r p; do
    [ -n "$p" ] || continue
    if [ -f "$p" ] && ! grep -qxF -- "$p" "$MANIFEST"; then del "$p"; fi
  done
  # 2. Phase 0 orphan split copies: BookProof/<X>/Part*.lean not in the new layout
  if [ -d BookProof ]; then
    find BookProof -type f -name 'Part*.lean' | sed 's#^\./##' | sort | while IFS= read -r p; do
      d=$(dirname "$p")
      if ! grep -qxF -- "$p" "$MANIFEST" && ! grep -q "^$d/" "$MANIFEST"; then del "$p"; fi
    done
    [ "$DRYRUN" = 1 ] || find BookProof -mindepth 1 -type d -empty -delete
  fi
fi
exit 0
